args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?bd ?label WHERE {
  VALUES ?person { dbr:Katrien_Aerts dbr:Giuliano_Rossi }
  OPTIONAL { ?person dbo:birthDate ?bd_dbo }
  OPTIONAL { ?person dbp:birthDate ?bd_dbp }
  BIND(COALESCE(?bd_dbo, ?bd_dbp) AS ?bd_val)
  BIND(xsd:date(?bd_val) AS ?bd)
  OPTIONAL { ?person rdfs:label ?label . FILTER(LANG(?label) = "en") }
}
ORDER BY ?bd
LIMIT 1

